const raw = $input.first().json;

// n8n Webhook can nest Meta payload in .body or put it at top level
const body = raw.body ?? raw;
const root = typeof body === 'string' ? JSON.parse(body) : body;
const value = root.entry?.[0]?.changes?.[0]?.value ?? root;

// Ignore delivery/read receipts quietly
if (value?.statuses && !value?.messages) {
  return [];
}

const messages = value?.messages;
const msg = Array.isArray(messages) ? messages[0] : messages;
if (!msg) {
  throw new Error('Webhook reached n8n but no WhatsApp text message found. Top keys: ' + Object.keys(raw || {}).join(', '));
}

const type = msg.type || (msg.text ? 'text' : '');
if (type && type !== 'text') {
  return [];
}

const text = (msg.text?.body || (typeof msg.text === 'string' ? msg.text : '') || '').toString().trim();
if (!text) return [];

const phone = String(msg.from || '').replace(/\D/g, '');
if (!phone) return [];

return [{
  json: {
    phone,
    text,
    wa_name: value.contacts?.[0]?.profile?.name || '',
    phone_number_id: value.metadata?.phone_number_id || '',
    message_id: msg.id || '',
  },
}];

const cfg = $('Client config').first().json;
const inbound = $('Extract inbound').first().json;
const row = $input.first().json || {};

const hasRow = Boolean(row.phone);
const fields = {
  name: hasRow ? (row.name || '') : '',
  budget_min: hasRow && row.budget_min !== '' && row.budget_min != null ? Number(row.budget_min) : null,
  budget_max: hasRow && row.budget_max !== '' && row.budget_max != null ? Number(row.budget_max) : null,
  locality: hasRow ? (row.locality || '') : '',
  timeline: hasRow ? (row.timeline || '') : '',
  purpose: hasRow && row.purpose ? row.purpose : 'unknown',
  bhk: hasRow ? (row.bhk || '') : '',
  notes: hasRow ? (row.notes || '') : '',
  lead_score: hasRow ? (row.lead_score || 'cold') : 'cold',
  notified: hasRow ? (row.notified || '') : '',
  transcript: [],
};

try {
  if (hasRow && row.transcript) fields.transcript = JSON.parse(row.transcript);
} catch (e) {
  fields.transcript = [];
}

fields.transcript.push({ role: 'user', content: inbound.text, at: new Date().toISOString() });

const priceLakh = Math.round(cfg.property_price_inr / 100000);
const history = fields.transcript.slice(-12).map((m) => `${m.role === 'user' ? 'Buyer' : 'LeadSpark'}: ${m.content}`).join('\n');

const system_prompt = `You are LeadSpark, a WhatsApp assistant for ${cfg.agent_name} at ${cfg.agent_company} (Indian real estate). You represent the agent's listing.\n\nPROPERTY\n- ${cfg.property_title}\n- ${cfg.property_bhk} BHK, ${cfg.property_furnishing}, ${cfg.property_locality}, ${cfg.property_city}\n- Price: ₹${priceLakh} Lakh (${cfg.property_price_inr} INR)\n- RERA: ${cfg.rera_number}\n\nGOAL: Over 3–5 short WhatsApp messages, capture name, budget, locality preference, timeline, purpose (self-use/investment), BHK preference. Phone is already ${inbound.phone}.\n\nTONE: Warm Indian English. Use BHK and ₹/Lakh/Cr. One question at a time. 2–4 sentences max.\n\nALREADY KNOWN:\n${JSON.stringify({ name: fields.name, budget_max: fields.budget_max, locality: fields.locality, timeline: fields.timeline, purpose: fields.purpose, bhk: fields.bhk }, null, 2)}\n\nReturn ONLY JSON with keys: reply, name, budget_min, budget_max, locality, timeline, purpose, bhk, notes.`;

const user_prompt = `Conversation so far:\n${history || '(new chat)'}\n\nLatest buyer message: ${inbound.text}`;

return [{ json: { ...inbound, ...cfg, prior: fields, gemini_body: { system_instruction: { parts: [{ text: system_prompt }] }, contents: [{ role: 'user', parts: [{ text: user_prompt }] }], generationConfig: { temperature: 0.4, responseMimeType: 'application/json' } } } }];

const prep = $('Prepare Gemini payload').first().json;
const inbound = $('Extract inbound').first().json;
const cfg = $('Client config').first().json;
const prior = prep.prior;
const gemini = $input.first().json;

function parseBudget(text) {
  const t = String(text || '').toLowerCase();
  const cr = t.match(/(\d+(?:\.\d+)?)\s*cr/);
  const lakh = t.match(/(\d+(?:\.\d+)?)\s*lakh/);
  if (cr) return Math.round(parseFloat(cr[1]) * 10000000);
  if (lakh) return Math.round(parseFloat(lakh[1]) * 100000);
  return null;
}

function score(f) {
  const hasPhone = String(inbound.phone || '').replace(/\D/g, '').length >= 10;
  const timeline = String(f.timeline || '').toLowerCase();
  const soon = /immediate|asap|this week|15 day|1 month|one month|within a month|urgent|ready|2 week|two week/.test(timeline);
  let budgetFit = false;
  const max = f.budget_max ?? f.budget_min;
  if (max != null) budgetFit = Number(max) >= cfg.property_price_inr * 0.8;
  if (f.budget_min != null && Number(f.budget_min) > cfg.property_price_inr * 1.3) budgetFit = false;
  if (hasPhone && budgetFit && soon) return 'hot';
  if (hasPhone && (budgetFit || soon)) return 'warm';
  if (hasPhone || max != null || f.name) return 'warm';
  return 'cold';
}

function fallbackReply(f) {
  const priceLakh = Math.round(cfg.property_price_inr / 100000);
  if (!f.name) return `Hi! Thanks for your interest in the ${cfg.property_bhk} BHK in ${cfg.property_locality}. I'm assisting ${cfg.agent_name} from ${cfg.agent_company}. May I know your name?`;
  if (f.budget_max == null) return `Nice to meet you, ${f.name}. This home is listed around ₹${priceLakh} Lakh. What's your budget range?`;
  if (!f.timeline) return `Understood on budget. Are you looking to finalise in the next few weeks, or still exploring?`;
  if (!f.purpose || f.purpose === 'unknown') return `Almost done — is this for your own stay or more of an investment?`;
  if (!f.bhk) return `And are you specifically looking for a ${cfg.property_bhk} BHK, or open to other configurations?`;
  return `Perfect, ${f.name}. I've noted your details for the ${cfg.property_locality} ${cfg.property_bhk} BHK. ${cfg.agent_name} will connect shortly.`;
}

let extracted = {};
try {
  const text = gemini.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const cleaned = String(text).replace(/```json|```/g, '').trim();
  if (cleaned.startsWith('{')) extracted = JSON.parse(cleaned);
} catch (e) { extracted = {}; }

const lower = inbound.text.toLowerCase();
let name = extracted.name || prior.name || '';
if (!name && /^[a-zA-Z][a-zA-Z\s]{1,40}$/.test(inbound.text.trim())) name = inbound.text.trim();

let purpose = extracted.purpose || prior.purpose || 'unknown';
if (/(self|own stay|end use|family|stay)/.test(lower)) purpose = 'self-use';
if (/invest/.test(lower)) purpose = 'investment';

let timeline = extracted.timeline || prior.timeline || '';
if (/(month|week|immediate|asap|urgent|year)/.test(lower) && !timeline) timeline = inbound.text.trim();

let bhk = extracted.bhk || prior.bhk || '';
const bhkMatch = lower.match(/(\d)\s*bhk/);
if (bhkMatch) bhk = `${bhkMatch[1]}BHK`;

const fields = {
  name: name || null,
  budget_min: extracted.budget_min ?? prior.budget_min,
  budget_max: extracted.budget_max ?? parseBudget(inbound.text) ?? prior.budget_max,
  locality: extracted.locality || prior.locality || cfg.property_locality,
  timeline: timeline || null,
  purpose,
  bhk: bhk || null,
  notes: extracted.notes || prior.notes || null,
};

const lead_score = score(fields);
const reply = (extracted.reply && String(extracted.reply).trim()) || fallbackReply(fields);
const transcript = [...(prior.transcript || []), { role: 'assistant', content: reply, at: new Date().toISOString() }];
const wasHot = prior.lead_score === 'hot' || prior.notified === 'yes';
const should_notify = lead_score === 'hot' && !wasHot;

return [{ json: {
  phone: inbound.phone,
  wa_name: inbound.wa_name,
  ...fields,
  lead_score,
  reply,
  transcript: JSON.stringify(transcript),
  notified: should_notify || prior.notified === 'yes' ? 'yes' : '',
  should_notify,
  status: 'open',
  updated_at: new Date().toISOString(),
  last_message: inbound.text,
  agent_email: cfg.agent_email,
  agent_name: cfg.agent_name,
  property_title: cfg.property_title,
  property_locality: cfg.property_locality,
  phone_number_id: inbound.phone_number_id,
}}];
